CREATE OR REPLACE FUNCTION operations.audit_metadata_is_safe(payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    metadata_key TEXT;
    metadata_type TEXT;
    metadata_value TEXT;
BEGIN
    IF jsonb_typeof(payload) <> 'object' THEN
        RETURN FALSE;
    END IF;

    FOR metadata_key IN SELECT jsonb_object_keys(payload)
    LOOP
        IF metadata_key NOT IN (
            'backup_id', 'checksum_sha256', 'size_bytes', 'encryption_key_id',
            'retention_until', 'restore_id', 'verified_object_count', 'query_limit',
            'result', 'failure_code', 'dependency', 'redaction_code'
        ) THEN
            RETURN FALSE;
        END IF;
        metadata_type := jsonb_typeof(payload -> metadata_key);
        metadata_value := payload ->> metadata_key;
        CASE metadata_key
            WHEN 'backup_id' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^backup-[A-Za-z0-9-]{1,120}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'checksum_sha256' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^[a-f0-9]{64}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'size_bytes' THEN
                IF metadata_type <> 'number'
                    OR metadata_value !~ '^[1-9][0-9]{0,15}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'encryption_key_id' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^[A-Za-z0-9_.:-]{1,128}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'retention_until' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'restore_id' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^restore-[A-Za-z0-9-]{1,120}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'verified_object_count', 'query_limit' THEN
                IF metadata_type <> 'number'
                    OR metadata_value !~ '^(0|[1-9][0-9]{0,9})$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'result' THEN
                IF metadata_type <> 'string'
                    OR metadata_value NOT IN ('SUCCEEDED', 'FAILED', 'DEGRADED', 'READY') THEN
                    RETURN FALSE;
                END IF;
            WHEN 'failure_code' THEN
                IF metadata_type <> 'string'
                    OR metadata_value !~ '^[A-Z][A-Z0-9_]{1,127}$' THEN
                    RETURN FALSE;
                END IF;
            WHEN 'dependency' THEN
                IF metadata_type <> 'string'
                    OR metadata_value NOT IN ('postgres', 'intake', 'outbox', 'redis', 'ai', 'ocr', 'object_storage') THEN
                    RETURN FALSE;
                END IF;
            WHEN 'redaction_code' THEN
                IF metadata_type <> 'string'
                    OR metadata_value NOT IN ('SECRET_FIELD', 'PATIENT_SENSITIVE_FIELD', 'MEDIA_REFERENCE_FIELD') THEN
                    RETURN FALSE;
                END IF;
        END CASE;
    END LOOP;
    RETURN TRUE;
END
$function$

CREATE OR REPLACE FUNCTION platform.sync_local_epoch_pair()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'platform'
AS $function$
DECLARE
    local_column text := TG_ARGV[0];
    epoch_column text := TG_ARGV[1];
    local_text text;
    epoch_text text;
    old_local_text text;
    old_epoch_text text;
    derived_epoch bigint;
    derived_local timestamp without time zone;
BEGIN
    local_text := to_jsonb(NEW) ->> local_column;
    epoch_text := to_jsonb(NEW) ->> epoch_column;
    IF TG_OP = 'UPDATE' THEN
        old_local_text := to_jsonb(OLD) ->> local_column;
        old_epoch_text := to_jsonb(OLD) ->> epoch_column;
    END IF;

    IF local_text IS NULL AND epoch_text IS NULL THEN
        RETURN NEW;
    END IF;

    IF epoch_text IS NULL
       OR (TG_OP = 'UPDATE' AND local_text IS DISTINCT FROM old_local_text
           AND epoch_text IS NOT DISTINCT FROM old_epoch_text) THEN
        derived_epoch := floor(extract(
            epoch FROM (local_text::timestamp without time zone AT TIME ZONE 'Asia/Shanghai')
        ) * 1000)::bigint;
        NEW := jsonb_populate_record(NEW, jsonb_build_object(epoch_column, derived_epoch));
        RETURN NEW;
    END IF;

    derived_local := platform.local_from_epoch_ms(epoch_text::bigint);
    IF local_text IS NULL
       OR (TG_OP = 'UPDATE' AND epoch_text IS DISTINCT FROM old_epoch_text
           AND local_text IS NOT DISTINCT FROM old_local_text) THEN
        NEW := jsonb_populate_record(NEW, jsonb_build_object(local_column, derived_local));
        RETURN NEW;
    END IF;

    IF local_text::timestamp without time zone <> derived_local THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'ARCH_005_LOCAL_EPOCH_PAIR_MISMATCH',
            DETAIL = format('%s.%s.%s/%s', TG_TABLE_SCHEMA, TG_TABLE_NAME, local_column, epoch_column);
    END IF;
    RETURN NEW;
END
$function$

